// topic: ahu-rig/<id>/telemetry   payload (json): { hmiValue, controllerValue?, confirmed?, ts? }
// Matches rig.js handleMessage 'telemetry': Object.assign(point, msg.payload) then recordSample.
const id = msg.topic.split('/')[1];
const p = msg.payload || {};

// Broadcast to all connected dashboards (no msg._session = broadcast).
msg = {
    payload: JSON.stringify({
        type: 'telemetry',
        payload: { id: id, hmiValue: p.hmiValue, controllerValue: p.controllerValue, confirmed: p.confirmed },
        ts: Date.now()
    })
};
return msg;

// The dashboard has no dedicated 'device connectivity' message type — it
// only understands the types listed in rig.js. We surface ESP32 dropouts
// through the existing alarm channel (shape confirmed against AlertPanel.vue:
// { id, severity, title, detail, ts }). Adjust if you add a proper
// 'device.status' type to rig.js later.
const online = msg.payload === 'online';
flow.set('deviceOnline', online);
if (online) return null; // no alarm needed on reconnect; UI clears via retained state on reload only

msg = {
    payload: JSON.stringify({
        type: 'alarm',
        payload: {
            id: 'device-esp32-01-offline',
            severity: 'critical',
            title: 'ESP32 rig disconnected',
            detail: 'Lost MQTT connection to esp32-ahu-rig-01 (Ethernet/broker link down).',
            ts: Date.now()
        },
        ts: Date.now()
    })
};
return msg;

// msg.payload is the raw JSON string sent by useWebSocket.js's send():
// { type, payload, ts }. IMPORTANT: keep returning the *same* msg object
// (mutating msg.payload only) wherever we want a unicast reply — Node-RED's
// websocket out node uses msg._session, set by websocket in, to reply to
// only the sending client. Building a brand-new {payload:...} object drops
// _session and broadcasts to every connected dashboard instead.
let env;
try { env = JSON.parse(msg.payload); }
catch (e) { node.warn('bad WS json: ' + msg.payload); return null; }

switch (env.type) {
    case 'ping': {
        msg.payload = JSON.stringify({ type: 'pong', payload: null, ts: Date.now() });
        return [msg, null, null, null, null]; // unicast back on same _session
    }
    case 'io.command': {
        // { id, value } -> stimulus command to ESP32
        return [null, {
            topic: `ahu-rig/${env.payload.id}/cmd`,
            payload: JSON.stringify({ value: env.payload.value }),
            qos: 0, retain: false
        }, null, null, null];
    }
    case 'sim.set': {
        return [null, null, {
            topic: 'ahu-rig/sim',
            payload: JSON.stringify({ on: !!env.payload.on }),
            qos: 1, retain: true
        }, null, null];
    }
    case 'sim.releaseAll': {
        return [null, null, null, {
            topic: 'ahu-rig/release',
            payload: '{}',
            qos: 1, retain: false
        }, null];
    }
    case 'io.add':
    case 'io.remove':
    case 'manual.entry':
    case 'manual.confirm': {
        // Now persisted — see "AHU Rig - Persistence & Storage Stats" tab.
        const pmsg = { payload: env };
        return [null, null, null, null, pmsg];
    }
    default:
        node.warn('[ws router] unhandled type: ' + env.type);
        return [null, null, null, null, null];
}

const p = msg.payload || {};
msg = {
    payload: JSON.stringify({ type: 'sim.status', payload: { on: !!p.on }, ts: Date.now() })
};
return msg;

// msg.payload = { type, payload, ts } (already-parsed object, not JSON string —
// see fn-ws-router's 5th output).
// Requires settings.js: functionGlobalContext: { fs: require('fs') }
const fs = global.get('fs');
const PLAN_FILE = '/home/pi/ahu-rig-data/testplan.json';
const AUDIT_FILE = '/home/pi/ahu-rig-data/audit-log.jsonl';
const env = msg.payload;

function loadPlan() {
    try {
        return JSON.parse(fs.readFileSync(PLAN_FILE, 'utf8'));
    } catch (e) {
        // First run / file missing — start from an empty shell. Seed it
        // properly by copying your real seedTestPlan.js output here once,
        // or POST it in via an admin flow — out of scope for this pass.
        return { sections: [] };
    }
}

function savePlan(plan) {
    fs.mkdirSync('/home/pi/ahu-rig-data', { recursive: true });
    fs.writeFileSync(PLAN_FILE, JSON.stringify(plan, null, 2));
}

function appendAudit(entry) {
    fs.mkdirSync('/home/pi/ahu-rig-data', { recursive: true });
    fs.appendFileSync(AUDIT_FILE, JSON.stringify(entry) + '\n');
}

function findPoint(plan, id) {
    for (const section of plan.sections) {
        const pt = (section.points || []).find(p => p.id === id);
        if (pt) return pt;
    }
    return null;
}

const plan = loadPlan();

switch (env.type) {
    case 'io.add': {
        // env.payload is expected to be a full point object. If your real
        // rig.js io.add action includes a target sectionId, adjust this —
        // it wasn't visible in the excerpt reviewed, so we default to the
        // first section (or create an 'Added Points' section) as a fallback.
        const point = env.payload;
        let section = plan.sections.find(s => s.id === point.sectionId) ||
                      plan.sections.find(s => s.id === 'added-points');
        if (!section) {
            section = { id: 'added-points', label: 'Added Points', points: [] };
            plan.sections.push(section);
        }
        section.points = section.points || [];
        section.points.push(point);
        break;
    }
    case 'io.remove': {
        const id = env.payload.id;
        for (const section of plan.sections) {
            section.points = (section.points || []).filter(p => p.id !== id);
        }
        break;
    }
    case 'manual.entry': {
        const pt = findPoint(plan, env.payload.id);
        if (pt) pt.controllerValue = env.payload.value;
        break;
    }
    case 'manual.confirm': {
        const pt = findPoint(plan, env.payload.id);
        if (pt) pt.confirmed = env.payload.confirmed;
        break;
    }
}

savePlan(plan);
appendAudit({ ts: Date.now(), type: env.type, payload: env.payload });

msg.payload = JSON.stringify({ type: 'testplan.set', payload: plan, ts: Date.now() });
return msg;

const fs = global.get('fs');
const PLAN_FILE = '/home/pi/ahu-rig-data/testplan.json';
let plan;
try {
    plan = JSON.parse(fs.readFileSync(PLAN_FILE, 'utf8'));
} catch (e) {
    node.warn('No persisted testplan.json yet (first run) — dashboard keeps using its bundled seedTestPlan.js until a point is added/edited.');
    return null;
}
msg.payload = JSON.stringify({ type: 'testplan.set', payload: plan, ts: Date.now() });
return msg;

const fs = global.get('fs');
const PLAN_FILE = '/home/pi/ahu-rig-data/testplan.json';
const AUDIT_FILE = '/home/pi/ahu-rig-data/audit-log.jsonl';

function sizeOf(path) {
    try { return fs.statSync(path).size; } catch (e) { return 0; }
}
function lineCountOf(path) {
    try {
        const txt = fs.readFileSync(path, 'utf8');
        return txt.split('\n').filter(Boolean).length;
    } catch (e) { return 0; }
}

msg.payload = JSON.stringify({
    type: 'storage.stats',
    payload: {
        testPlanBytes: sizeOf(PLAN_FILE),
        auditLogEntries: lineCountOf(AUDIT_FILE),
        auditLogBytes: sizeOf(AUDIT_FILE),
        lastCheckedAt: Date.now()
    },
    ts: Date.now()
});
return msg;

// topic: ahu-rig/<id>/cmd/ack   payload: { value }
const id = msg.topic.split('/')[1];
const p = msg.payload || {};
msg = {
    payload: JSON.stringify({ type: 'io.commanded', payload: { id: id, value: p.value }, ts: Date.now() })
};
return msg;

// See esp32_ahu_rig.ino's otaRollbackInit/otaNoteHealthySample/otaCheckTimeout —
// this is the visibility layer for that rollback mechanism on the dashboard.
const p = msg.payload || {};
let title, detail, severity;

switch (p.state) {
    case 'updating':
        title = 'ESP32 firmware update started';
        detail = 'New OTA image is being flashed over WiFi.';
        severity = 'caution';
        break;
    case 'validated':
        title = 'ESP32 firmware update confirmed healthy';
        detail = 'New firmware passed its post-update health check (Ethernet + MQTT + telemetry). No rollback needed.';
        severity = 'caution';
        break;
    case 'rolling_back':
        title = 'ESP32 firmware update FAILED — rolling back automatically';
        detail = 'Reason: ' + (p.reason || 'unknown') + '. Reverting to the previous known-good firmware and rebooting.';
        severity = 'critical';
        break;
    default:
        return null;
}

msg = {
    payload: JSON.stringify({
        type: 'alarm',
        payload: { id: 'esp32-ota-' + Date.now(), severity, title, detail, ts: Date.now() },
        ts: Date.now()
    })
};
return msg;
